                    ${latestRelease}
                    ${summary}
                    <mj-section>
                        <mj-column>
                            ${issues.join(`<mj-divider  border-width="1px" border-color="#D3D3D3"/>`)}
                        </mj-column>
                    </mj-section>
                </mj-wrapper>
        </mj-body>
        </mjml>`
}

