	if (isFreeModel(item)) {
		freeModels.push(item)
		if (isReliableProvider(item)) {
			reliableModels.push(item)
		} 
	}
}

var selectedModels = reliableModels || freeModels; 
selectedModels.sort((a, b) => b.created - a.created);
